import{_ as e,o as l,c as i,a5 as n,j as s,a as t,t as r}from"./chunks/framework.Bt0SrEfo.js";const S=JSON.parse('{"title":"微信小程序是什么？和 H5 的区别是什么？","description":"","frontmatter":{},"headers":[],"relativePath":"面试/高频Q&A/小程序/2-basics.md","filePath":"面试/高频Q&A/小程序/2-basics.md","lastUpdated":1789788214000}'),p={name:"面试/高频Q&A/小程序/2-basics.md"};function d(o,a,h,c,g,b){return l(),i("div",null,[a[4]||(a[4]=n(`<h1 id="微信小程序是什么-和-h5-的区别是什么" tabindex="-1">微信小程序是什么？和 H5 的区别是什么？ <a class="header-anchor" href="#微信小程序是什么-和-h5-的区别是什么" aria-label="Permalink to &quot;微信小程序是什么？和 H5 的区别是什么？&quot;">​</a></h1><blockquote><p>📚 <strong>深度专题推荐</strong>：本文是关于「小程序基础架构」的精炼回答。面试高频题，重点理解双线程模型。</p></blockquote><hr><h2 id="一、微信小程序是什么" tabindex="-1">一、微信小程序是什么？ <a class="header-anchor" href="#一、微信小程序是什么" aria-label="Permalink to &quot;一、微信小程序是什么？&quot;">​</a></h2><p>一种<strong>运行在微信内部</strong>的应用形态：</p><ul><li>不需要下载安装（用户扫一扫 / 搜一搜直接打开）</li><li>不是 H5，也不是原生 App，是介于两者之间的特殊形态</li><li>使用 <strong>WXML + WXSS + JS</strong>（类 HTML + CSS + JS 的自定义方言）</li></ul><hr><h2 id="二、双线程架构-核心" tabindex="-1">二、双线程架构（核心） <a class="header-anchor" href="#二、双线程架构-核心" aria-label="Permalink to &quot;二、双线程架构（核心）&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>┌──────────────────────────────────────────┐</span></span>
<span class="line"><span>│                  微信客户端                  │</span></span>
<span class="line"><span>├──────────────────────────────────────────┤</span></span>
<span class="line"><span>│                                            │</span></span>
<span class="line"><span>│  ┌────────────────┐   ┌────────────────┐  │</span></span>
<span class="line"><span>│  │   视图线程      │   │   逻辑线程       │  │</span></span>
<span class="line"><span>│  │  (WebView)     │   │  (JSCore/V8)   │  │</span></span>
<span class="line"><span>│  │                │   │                │  │</span></span>
<span class="line"><span>│  │  渲染 WXML     │   │  执行 JS 代码    │  │</span></span>
<span class="line"><span>│  │  处理交互事件   │   │  调用 wx API    │  │</span></span>
<span class="line"><span>│  └────────┬───────┘   └────────┬───────┘  │</span></span>
<span class="line"><span>│           │   JSBridge 通信    │           │</span></span>
<span class="line"><span>│           └────────┬───────────┘           │</span></span>
<span class="line"><span>│                    │                       │</span></span>
<span class="line"><span>│              ┌─────▼──────┐                │</span></span>
<span class="line"><span>│              │  Native 层  │                │</span></span>
<span class="line"><span>│              │ (微信原生)   │                │</span></span>
<span class="line"><span>│              └────────────┘                │</span></span>
<span class="line"><span>└──────────────────────────────────────────┘</span></span></code></pre></div><h3 id="两个线程的分工" tabindex="-1">两个线程的分工 <a class="header-anchor" href="#两个线程的分工" aria-label="Permalink to &quot;两个线程的分工&quot;">​</a></h3><table tabindex="0"><thead><tr><th>线程</th><th>负责</th><th>不能做</th></tr></thead><tbody><tr><td><strong>视图线程</strong>（WebView）</td><td>渲染 WXML/WXSS、处理用户交互</td><td>不能直接调用 wx API</td></tr><tr><td><strong>逻辑线程</strong>（JSCore）</td><td>执行 JS 业务逻辑、调用 wx API</td><td>不能直接操作 DOM</td></tr><tr><td><strong>Native 层</strong></td><td>提供 wx API、文件、网络、存储等系统能力</td><td>—</td></tr></tbody></table><h3 id="为什么是双线程" tabindex="-1">为什么是双线程？ <a class="header-anchor" href="#为什么是双线程" aria-label="Permalink to &quot;为什么是双线程？&quot;">​</a></h3><ol><li><strong>安全</strong>：JS 在沙箱里跑，不能直接操作 DOM（防 XSS / 跳转）</li><li><strong>可控</strong>：渲染层由 WebView 管理，逻辑层由微信管控 → App 行为可控</li><li><strong>流畅</strong>：逻辑层不阻塞渲染层（异步通信）</li></ol><h3 id="jsbridge-通信流程-重要" tabindex="-1">JSBridge 通信流程（重要） <a class="header-anchor" href="#jsbridge-通信流程-重要" aria-label="Permalink to &quot;JSBridge 通信流程（重要）&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>用户点击按钮</span></span>
<span class="line"><span>  ↓ 视图层（WebView）</span></span>
<span class="line"><span>触发 bindtap 事件</span></span>
<span class="line"><span>  ↓ WebView 把事件序列化，通过 JSBridge 发给逻辑层</span></span>
<span class="line"><span>逻辑层收到事件</span></span>
<span class="line"><span>  ↓ JSCore 执行回调函数</span></span>
<span class="line"><span>this.setData({ ... })</span></span>
<span class="line"><span>  ↓ 逻辑层把数据序列化，通过 JSBridge 发回视图层</span></span>
<span class="line"><span>  ↓ 视图层更新 DOM</span></span></code></pre></div><hr><h2 id="三、和-h5-的区别" tabindex="-1">三、和 H5 的区别 <a class="header-anchor" href="#三、和-h5-的区别" aria-label="Permalink to &quot;三、和 H5 的区别&quot;">​</a></h2><table tabindex="0"><thead><tr><th>维度</th><th>H5</th><th>小程序</th></tr></thead><tbody><tr><td>运行环境</td><td>浏览器</td><td>微信（WebView + JSCore 双线程）</td></tr><tr><td>渲染</td><td>HTML + CSS</td><td>WXML + WXSS（类 HTML/CSS）</td></tr><tr><td>开发语言</td><td>JS</td><td>JS（无 DOM/BOM API）</td></tr><tr><td>系统能力</td><td>受浏览器限制</td><td>wx.* API（扫码、定位、支付、获取微信用户信息等）</td></tr><tr><td>性能</td><td>一般</td><td>比 H5 快（双线程隔离 + 预加载）</td></tr><tr><td>体积限制</td><td>无</td><td>单包 2MB（主包），总计 16MB</td></tr><tr><td>上线审核</td><td>否</td><td>需要微信审核</td></tr><tr><td>入口</td><td>URL</td><td>扫码、搜一搜、分享卡</td></tr></tbody></table><hr><h2 id="四、为什么小程序启动快" tabindex="-1">四、为什么小程序启动快？ <a class="header-anchor" href="#四、为什么小程序启动快" aria-label="Permalink to &quot;四、为什么小程序启动快？&quot;">​</a></h2><ol><li><strong>预加载 WebView</strong>：用户访问过的小程序，微信会缓存 WebView</li><li><strong>资源预下载</strong>：分包加载，主包 + 分包</li><li><strong>双线程隔离</strong>：逻辑层不阻塞渲染层</li></ol><hr><h2 id="五、面试追问" tabindex="-1">五、面试追问 <a class="header-anchor" href="#五、面试追问" aria-label="Permalink to &quot;五、面试追问&quot;">​</a></h2><p><strong>Q：双线程有什么缺点？</strong></p><p>A：线程间通信有<strong>序列化开销</strong>，频繁 setData 会卡顿。所以 setData 要尽量：</p><ul><li>单次设置多个字段（合并）</li><li>数据量不能太大（建议 &lt; 256KB）</li><li>不要在循环里调用</li></ul><p><strong>Q：小程序可以操作 DOM 吗？</strong></p><p>A：<strong>不能</strong>。微信沙箱环境不暴露 DOM/BOM API。只能通过 <code>this.setData()</code> 更新数据 → 框架 diff → 视图更新。</p><p><strong>Q：小程序的 WXML 和 HTML 的核心区别？</strong></p><p>A：</p>`,30)),s("ul",null,[a[2]||(a[2]=n("<li>WXML 用 <code>&lt;view&gt;</code> <code>&lt;text&gt;</code> 而不是 <code>&lt;div&gt;</code> <code>&lt;span&gt;</code>（性能优化）</li><li>标签属性用 <code>bindtap</code> 而不是 <code>onclick</code></li>",2)),s("li",null,[a[0]||(a[0]=t("数据绑定用 ",-1)),s("code",null,r(),1),a[1]||(a[1]=t("，类似 Vue 的 Mustache",-1))]),a[3]||(a[3]=s("li",null,[t("支持 "),s("code",null,"wx:if"),t("、"),s("code",null,"wx:for"),t(" 指令")],-1))]),a[5]||(a[5]=s("hr",null,null,-1)),a[6]||(a[6]=s("h2",{id:"参考文献",tabindex:"-1"},[t("参考文献 "),s("a",{class:"header-anchor",href:"#参考文献","aria-label":'Permalink to "参考文献"'},"​")],-1)),a[7]||(a[7]=s("ul",null,[s("li",null,[s("a",{href:"https://developers.weixin.qq.com/miniprogram/dev/framework/",target:"_blank",rel:"noreferrer"},"https://developers.weixin.qq.com/miniprogram/dev/framework/")])],-1))])}const m=e(p,[["render",d]]);export{S as __pageData,m as default};
